INSERT INTO question_content (id, question_id, stem, lead_in, numeric_answer, numeric_tolerance, numeric_unit, decimal_places, calculator_allowed, calculation_working, created_at, updated_at) VALUES ('fdd02102-1c48-4a1c-9fbb-917e0d8fb72e', '7af09f71-55d5-4080-9e42-18dab1da2bd6', 'A private prescription for Morphine sulfate 10 mg tablets (Schedule 2 CD) is presented at a community pharmacy. The prescription is dated 32 days ago and specifies total quantity as 56 tablets without words and figures. (Case Ref: PHARMACY-LAW-1001). Relevant physiological and medication history have been reviewed.', 'Can the pharmacist legally dispense this prescription?', NULL, NULL, NULL, NULL, 1, NULL, 1789735204, 1789735204);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('ab7464ca-bb3e-48de-aa3d-ab2f41e13758', '7af09f71-55d5-4080-9e42-18dab1da2bd6', 'A', 'No, because Schedule 2 prescriptions are valid for only 28 days from date of signing and require total quantity in words and figures', 1, 'Correct. Schedule 2, 3, and 4 Controlled Drug prescriptions are legally valid for 28 days only. Schedule 2 and 3 prescriptions mandate total quantity in both words and figures.', 0, 1789735204);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('cb14c354-0392-44bc-9b24-e665d6cca7f9', '7af09f71-55d5-4080-9e42-18dab1da2bd6', 'B', 'Dispense half the quantity and request an amended prescription for the balance', 0, 'Illegal. An invalid CD prescription cannot be partially dispensed.', 1, 1789735204);
