INSERT INTO question_governance (id, question_id, clinical_approved_at, educational_approved_at, copy_editor_approved_at, approved_at, conflict_of_interest, created_at, updated_at) VALUES ('d69706d3-b020-444e-828b-656a7781e09a', '71fc5a3a-d64f-429f-ad26-72b7f7404dcc', 1789735204, 1789735204, 1789735204, 1789735204, 0, 1789735204, 1789735204);
INSERT INTO questions (id, public_id, version, status, pathway_id, primary_subtopic_id, difficulty, question_type, sector, origin, published_at, created_at, updated_at) VALUES ('edb6dcea-b46d-45dc-969e-47ee48361cf3', 'ACP-Q-1030', 1, 'published', 'p-mpharm', 'sub-vet', 'easy', 'sba', 'community', 'human', 1789735204, 1789735204, 1789735204);
INSERT INTO question_content (id, question_id, stem, lead_in, numeric_answer, numeric_tolerance, numeric_unit, decimal_places, calculator_allowed, calculation_working, created_at, updated_at) VALUES ('a8ea81e4-bfdf-45d2-89bd-e9e1ac7d49c3', 'edb6dcea-b46d-45dc-969e-47ee48361cf3', 'A private prescription for Morphine sulfate 10 mg tablets (Schedule 2 CD) is presented at a community pharmacy. The prescription is dated 32 days ago and specifies total quantity as 56 tablets without words and figures. (Case Ref: PHARMACY-LAW-1030). Relevant physiological and medication history have been reviewed.', 'Can the pharmacist legally dispense this prescription?', NULL, NULL, NULL, NULL, 1, NULL, 1789735204, 1789735204);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('2036850c-184a-4eac-801a-5da050d6c094', 'edb6dcea-b46d-45dc-969e-47ee48361cf3', 'A', 'No, because Schedule 2 prescriptions are valid for only 28 days from date of signing and require total quantity in words and figures', 1, 'Correct. Schedule 2, 3, and 4 Controlled Drug prescriptions are legally valid for 28 days only. Schedule 2 and 3 prescriptions mandate total quantity in both words and figures.', 0, 1789735204);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('45f72cb1-bc01-4173-9345-ec8cba5fbf27', 'edb6dcea-b46d-45dc-969e-47ee48361cf3', 'B', 'Dispense half the quantity and request an amended prescription for the balance', 0, 'Illegal. An invalid CD prescription cannot be partially dispensed.', 1, 1789735204);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('033e6a39-ba58-49e9-924a-7f597e546f1c', 'edb6dcea-b46d-45dc-969e-47ee48361cf3', 'C', 'Dispense the full supply and annotate the words and figures manually without prescriber amendment', 0, 'Illegal for total quantity. Pharmacists may only amend minor spelling/typographical errors or words/figures if omitted in specific limited home office circular exemptions.', 2, 1789735204);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('6dcc9792-9020-4e66-b8e9-a88aec3211e3', 'edb6dcea-b46d-45dc-969e-47ee48361cf3', 'D', 'Accept validity for 6 months as per standard prescription rules', 0, 'Standard POMs are valid for 6 months, but Controlled Drugs (Schedule 2-4) expire at 28 days.', 3, 1789735204);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('a3059381-453d-4795-805b-65f85f65cbaf', 'edb6dcea-b46d-45dc-969e-47ee48361cf3', 'E', 'Dispense under emergency supply regulations', 0, 'Schedule 2 and 3 CDs cannot be supplied under emergency supply regulations at patient request (except phenobarbital for epilepsy).', 4, 1789735204);
INSERT INTO question_explanations (id, question_id, summary_takeaway, detailed_explanation, clinical_guidance_reference, created_at, updated_at) VALUES ('a5aa292f-f2cf-481d-b2e6-22440588caa2', 'edb6dcea-b46d-45dc-969e-47ee48361cf3', 'Schedule 2 and 3 CD prescriptions are valid for 28 days and must contain quantity in both words and figures.', 'Installment prescriptions (FP10MDA) must have the first installment dispensed within 28 days of signing. Reference: Misuse of Drugs Regulations 2001 & MEP 46.', 'Misuse of Drugs Regulations 2001 & MEP 46', 1789735204, 1789735204);
INSERT INTO question_governance (id, question_id, clinical_approved_at, educational_approved_at, copy_editor_approved_at, approved_at, conflict_of_interest, created_at, updated_at) VALUES ('092bbd83-517a-4f3b-805b-e26a51e1a6f9', 'edb6dcea-b46d-45dc-969e-47ee48361cf3', 1789735204, 1789735204, 1789735204, 1789735204, 0, 1789735204, 1789735204);
INSERT INTO questions (id, public_id, version, status, pathway_id, primary_subtopic_id, difficulty, question_type, sector, origin, published_at, created_at, updated_at) VALUES ('45396a04-0746-4fee-a22b-aaec85eda1a4', 'ACP-Q-1031', 1, 'published', 'p-mpharm', 'sub-uti-first', 'hard', 'sba', 'gp', 'human', 1789735204, 1789735204, 1789735204);
INSERT INTO question_content (id, question_id, stem, lead_in, numeric_answer, numeric_tolerance, numeric_unit, decimal_places, calculator_allowed, calculation_working, created_at, updated_at) VALUES ('1c913d47-57d0-4e04-965e-6d3eae826d09', '45396a04-0746-4fee-a22b-aaec85eda1a4', 'A 24-year-old male attends community pharmacy with a severe sore throat of 2 days duration. Examination shows purulent tonsillar exudate, severe tonsillar inflammation, temperature 38.6°C, and no cough. FeverPAIN score is calculated as 4. (Case Ref: PHARMACY-FIRST-1031). Relevant physiological and medication history have been reviewed.', 'What is the appropriate action under the Pharmacy First clinical protocol?', NULL, NULL, NULL, NULL, 1, NULL, 1789735204, 1789735204);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('15fb5ade-c6a2-4615-bd05-224211a80599', '45396a04-0746-4fee-a22b-aaec85eda1a4', 'A', 'Supply Phenoxymethylpenicillin (Penicillin V) 500 mg QDS for 5 days under PGD with self-care and worsening advice', 1, 'Correct. FeverPAIN score >= 4 indicates high likelihood of streptococcal infection. Penicillin V is first-line under PGD for 5 days.', 0, 1789735204);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('0aaf571a-af4b-4a66-8dce-99b3a49cfc03', '45396a04-0746-4fee-a22b-aaec85eda1a4', 'B', 'Supply Clarithromycin 500 mg BD without checking for penicillin allergy', 0, 'Sub-optimal. Macrolides are reserved strictly for patients with true penicillin allergy due to resistance stewardship.', 1, 1789735204);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('7236ab16-60b1-412d-b686-624afada278b', '45396a04-0746-4fee-a22b-aaec85eda1a4', 'C', 'Supply Dexamethasone 8 mg stat dose for throat swelling without physician review', 0, 'Contraindicated under community pharmacy protocol. High-dose oral corticosteroids are not authorized under this PGD.', 2, 1789735204);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('6fba66a9-6605-4706-9226-28d647546cee', '45396a04-0746-4fee-a22b-aaec85eda1a4', 'D', 'Supply Co-amoxiclav 625 mg TDS', 0, 'Inappropriate broad-spectrum antibiotic. Amoxicillin/co-amoxiclav may cause severe morbilliform rash in undiagnosed glandular fever (EBV).', 3, 1789735204);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('ce51e1cd-1af7-466f-ae87-7007bba0716b', '45396a04-0746-4fee-a22b-aaec85eda1a4', 'E', 'Supply Penicillin V for 14 days', 0, 'NICE NG84 guidelines mandate a 5-day course for acute group A streptococcal pharyngitis.', 4, 1789735204);
INSERT INTO question_explanations (id, question_id, summary_takeaway, detailed_explanation, clinical_guidance_reference, created_at, updated_at) VALUES ('9768ec33-8be6-4d27-a4a3-3785219355c0', '45396a04-0746-4fee-a22b-aaec85eda1a4', 'FeverPAIN score 4-5 warrants targeted antimicrobial treatment (Penicillin V for 5 days). Avoid amoxicillin if glandular fever is suspected.', 'FeverPAIN components: Fever, Purulent tonsils, Attend in <= 3 days, Inflamed tonsils, No cough/coryza. Reference: NHS England Pharmacy First Clinical Pathway & NICE NG84.', 'NHS England Pharmacy First Clinical Pathway & NICE NG84', 1789735204, 1789735204);
