INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('26761be9-b741-428d-88ae-edcec10b37a9', 'f200220d-8faa-4612-ac1b-ae7d7e6a14bd', 'A', 'Supply Phenoxymethylpenicillin (Penicillin V) 500 mg QDS for 5 days under PGD with self-care and worsening advice', 1, 'Correct. FeverPAIN score >= 4 indicates high likelihood of streptococcal infection. Penicillin V is first-line under PGD for 5 days.', 0, 1789735204);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('0ae94505-6e46-4687-94d2-6639300b9512', 'f200220d-8faa-4612-ac1b-ae7d7e6a14bd', 'B', 'Supply Clarithromycin 500 mg BD without checking for penicillin allergy', 0, 'Sub-optimal. Macrolides are reserved strictly for patients with true penicillin allergy due to resistance stewardship.', 1, 1789735204);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('aa79a8fa-98b2-4307-ab38-6825214cb3b5', 'f200220d-8faa-4612-ac1b-ae7d7e6a14bd', 'C', 'Supply Dexamethasone 8 mg stat dose for throat swelling without physician review', 0, 'Contraindicated under community pharmacy protocol. High-dose oral corticosteroids are not authorized under this PGD.', 2, 1789735204);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('07d68bc5-0261-4d79-b8fd-b612f66298d3', 'f200220d-8faa-4612-ac1b-ae7d7e6a14bd', 'D', 'Supply Co-amoxiclav 625 mg TDS', 0, 'Inappropriate broad-spectrum antibiotic. Amoxicillin/co-amoxiclav may cause severe morbilliform rash in undiagnosed glandular fever (EBV).', 3, 1789735204);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('cec1c4a2-0be1-4f54-8b5d-63aa499d9924', 'f200220d-8faa-4612-ac1b-ae7d7e6a14bd', 'E', 'Supply Penicillin V for 14 days', 0, 'NICE NG84 guidelines mandate a 5-day course for acute group A streptococcal pharyngitis.', 4, 1789735204);
INSERT INTO question_explanations (id, question_id, summary_takeaway, detailed_explanation, clinical_guidance_reference, created_at, updated_at) VALUES ('98992e5e-9832-44c3-b8fe-13f7feac4c51', 'f200220d-8faa-4612-ac1b-ae7d7e6a14bd', 'FeverPAIN score 4-5 warrants targeted antimicrobial treatment (Penicillin V for 5 days). Avoid amoxicillin if glandular fever is suspected.', 'FeverPAIN components: Fever, Purulent tonsils, Attend in <= 3 days, Inflamed tonsils, No cough/coryza. Reference: NHS England Pharmacy First Clinical Pathway & NICE NG84.', 'NHS England Pharmacy First Clinical Pathway & NICE NG84', 1789735204, 1789735204);
INSERT INTO question_governance (id, question_id, clinical_approved_at, educational_approved_at, copy_editor_approved_at, approved_at, conflict_of_interest, created_at, updated_at) VALUES ('3ea740aa-86be-4351-9c7a-1f1d3f842672', 'f200220d-8faa-4612-ac1b-ae7d7e6a14bd', 1789735204, 1789735204, 1789735204, 1789735204, 0, 1789735204, 1789735204);
INSERT INTO questions (id, public_id, version, status, pathway_id, primary_subtopic_id, difficulty, question_type, sector, origin, published_at, created_at, updated_at) VALUES ('1c5f0f3f-b787-43d6-a822-353493bfecfa', 'ACP-Q-1136', 1, 'published', 'p-mpharm', 'sub-gerd', 'hard', 'sba', 'gp', 'human', 1789735204, 1789735204, 1789735204);
INSERT INTO question_content (id, question_id, stem, lead_in, numeric_answer, numeric_tolerance, numeric_unit, decimal_places, calculator_allowed, calculation_working, created_at, updated_at) VALUES ('b20965d6-c529-4048-9414-7c4c36218c95', '1c5f0f3f-b787-43d6-a822-353493bfecfa', 'A 45-year-old patient with confirmed H. pylori on stool antigen test has no known drug allergies and has not taken macrolide antibiotics previously. (Case Ref: GASTROINTESTINAL-1136). Relevant physiological and medication history have been reviewed.', 'Which 7-day eradication regimen is recommended first-line by NICE?', NULL, NULL, NULL, NULL, 1, NULL, 1789735204, 1789735204);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('d57e27c9-ae3b-47d6-80d8-a330a82d63d2', '1c5f0f3f-b787-43d6-a822-353493bfecfa', 'A', 'PPI twice daily + Amoxicillin 1 g twice daily + Clarithromycin 500 mg twice daily for 7 days', 1, 'Correct. Standard UK first-line triple eradication consists of a full-dose PPI bd + amoxicillin 1g bd + clarithromycin 500mg bd (or metronidazole 400mg bd) for 7 days.', 0, 1789735204);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('a799972a-588e-457c-a4fd-b05553818383', '1c5f0f3f-b787-43d6-a822-353493bfecfa', 'B', 'PPI once daily + Amoxicillin 500 mg TDS for 14 days without second antibiotic', 0, 'Sub-optimal. Dual therapy has poor eradication rates; two synergic antibiotics plus twice-daily acid suppression are essential.', 1, 1789735204);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('0f6c4bcd-a9ee-4022-8386-deb6c36e39d7', '1c5f0f3f-b787-43d6-a822-353493bfecfa', 'C', 'Prescribe Clarithromycin in a patient taking concurrent Simvastatin 40 mg', 0, 'Dangerous interaction. Strong CYP3A4 inhibition increases statin exposure exponentially, causing rhabdomyolysis.', 2, 1789735204);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('5b97610a-107a-414d-bdb8-5410aca4341c', '1c5f0f3f-b787-43d6-a822-353493bfecfa', 'D', 'Triple therapy containing Ranitidine instead of PPI', 0, 'Deprecated and unavailable; ranitidine was withdrawn globally due to NDMA impurities.', 3, 1789735204);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('34e43d31-461e-4b73-a4ca-ec64c2b1d525', '1c5f0f3f-b787-43d6-a822-353493bfecfa', 'E', 'Retest H. pylori via stool antigen 2 days after completing antibiotics', 0, 'False-negative result. Wait at least 4 weeks post-antibiotics and 2 weeks post-PPI before retesting.', 4, 1789735204);
INSERT INTO question_explanations (id, question_id, summary_takeaway, detailed_explanation, clinical_guidance_reference, created_at, updated_at) VALUES ('5d12a159-adfe-4987-bbb5-192e0f83b5bf', '1c5f0f3f-b787-43d6-a822-353493bfecfa', 'H. pylori eradication requires 7 days of PPI bd + two antibiotics. Retest at least 4 weeks after treatment.', 'If penicillin allergic: PPI bd + Clarithromycin 250mg bd + Metronidazole 400mg bd. Reference: NICE NG184: Gastro-oesophageal reflux disease and dyspepsia.', 'NICE NG184: Gastro-oesophageal reflux disease and dyspepsia', 1789735204, 1789735204);
